INSERT INTO presets (id, name, badge, duration_minutes, positive_marks, negative_marks, default_count, sort_order) VALUES ('NEET_BIO', 'NEET Biology', 'Medical Entrance / Biology', 45, 4, 1, 40, 7);
INSERT INTO preset_sections (preset_id, position, name, topics, weight) VALUES ('NEET_BIO', 1, 'Botany', 'Plant cell and organelles, chloroplast, photosynthesis (C3 and C4), flower structure, double fertilisation, plant kingdom, plant physiology, cell cycle and mitosis', 25);
INSERT INTO preset_sections (preset_id, position, name, topics, weight) VALUES ('NEET_BIO', 2, 'Zoology', 'Animal cell organelles, mitochondria, human heart and circulation, nephron and excretion, neuron and synapse, human eye, muscle contraction, endocrine system, digestion, breathing', 30);
INSERT INTO preset_sections (preset_id, position, name, topics, weight) VALUES ('NEET_BIO', 3, 'Genetics & Evolution', 'Mendelian genetics, Punnett squares, pedigree analysis, DNA structure, replication, transcription, translation, lac operon, Hardy-Weinberg principle, evolution', 30);
INSERT INTO preset_sections (preset_id, position, name, topics, weight) VALUES ('NEET_BIO', 4, 'Ecology & Environment', 'Energy flow, ecological pyramids, food chains, nutrient cycles, succession, population growth, biodiversity, environmental issues', 15);
INSERT INTO exams (slug, title, source, status, duration_minutes, positive_marks, negative_marks, include_diagrams) VALUES ('neet-bio', 'NEET Biology: Botany, Zoology & Genetics', 'demo', 'ready', 45, 4, 1, 1);
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 1, 'Botany', 'Plant Cell Organelles (Diagram)', 'Easy', 'In the plant cell shown, the organelle labelled B is absent from animal cells and contains stacks of thylakoids (grana). What is its main function?', 1, '<svg viewBox="0 0 480 316" xmlns="http://www.w3.org/2000/svg"><rect width="480" height="316" fill="#f8fafc" rx="12"/><g transform="translate(20 14)"><rect x="40" y="25" width="360" height="235" rx="14" fill="#dcfce7" stroke="#15803d" stroke-width="10"/><rect x="49" y="34" width="342" height="217" rx="9" fill="#f7fee7" stroke="#84cc16" stroke-width="2"/><rect x="95" y="72" width="170" height="140" rx="32" fill="#bae6fd" stroke="#0369a1" stroke-width="2.5"/><circle cx="330" cy="100" r="36" fill="#e0e7ff" stroke="#4338ca" stroke-width="3"/><circle cx="338" cy="94" r="10" fill="#4338ca"/><g transform="translate(322 200)"><ellipse rx="36" ry="17" fill="#4ade80" stroke="#166534" stroke-width="2.5"/><rect x="-20" y="-9" width="9" height="18" rx="2" fill="#166534"/><rect x="-4" y="-9" width="9" height="18" rx="2" fill="#166534"/><rect x="12" y="-9" width="9" height="18" rx="2" fill="#166534"/></g><g transform="translate(168 236)"><ellipse rx="36" ry="17" fill="#4ade80" stroke="#166534" stroke-width="2.5"/><rect x="-20" y="-9" width="9" height="18" rx="2" fill="#166534"/><rect x="-4" y="-9" width="9" height="18" rx="2" fill="#166534"/><rect x="12" y="-9" width="9" height="18" rx="2" fill="#166534"/></g><g transform="translate(285 238) rotate(-8) scale(0.7)"><ellipse rx="34" ry="17" fill="#fde68a" stroke="#b45309" stroke-width="2.5"/><path d="M-24 0 l6 -10 l6 20 l6 -20 l6 20 l6 -20 l6 20 l6 -10" fill="none" stroke="#b45309" stroke-width="1.7"/></g><g class="tg"><line x1="44" y1="150" x2="12" y2="130" stroke="#334155" stroke-width="1.5"/><circle cx="44" cy="150" r="3" fill="#334155"/></g><g class="tg"><circle cx="12" cy="130" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="12" y="130.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">D</text></g><g class="tg"><line x1="180" y1="120" x2="180" y2="-2" stroke="#334155" stroke-width="1.5"/><circle cx="180" cy="120" r="3" fill="#334155"/></g><g class="tg"><circle cx="180" cy="-2" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="180" y="-1.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">A</text></g><g class="tg"><line x1="345" y1="203" x2="428" y2="218" stroke="#334155" stroke-width="1.5"/><circle cx="345" cy="203" r="3" fill="#334155"/></g><g class="tg"><circle cx="428" cy="218" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="428" y="218.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">B</text></g><g class="tg"><line x1="352" y1="88" x2="428" y2="60" stroke="#334155" stroke-width="1.5"/><circle cx="352" cy="88" r="3" fill="#334155"/></g><g class="tg"><circle cx="428" cy="60" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="428" y="60.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">E</text></g><g class="tg"><line x1="295" y1="240" x2="380" y2="285" stroke="#334155" stroke-width="1.5"/><circle cx="295" cy="240" r="3" fill="#334155"/></g><g class="tg"><circle cx="380" cy="285" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="380" y="285.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">C</text></g></g></svg>', 'Chloroplasts contain chlorophyll in the thylakoid membranes (light reactions) and the stroma (Calvin cycle), so they are the site of photosynthesis. Respiration happens in mitochondria and digestion in lysosomes.', 'D');
