slate(187 78) rotate(30)" d="M-8 -10 L8 10 M8 -10 L-8 10" stroke="#7c3aed" stroke-width="4.5" stroke-linecap="round"/><path transform="translate(219 72) rotate(-20)" d="M-8 -10 L8 10 M8 -10 L-8 10" stroke="#7c3aed" stroke-width="4.5" stroke-linecap="round"/><path transform="translate(225 100) rotate(60)" d="M-8 -10 L8 10 M8 -10 L-8 10" stroke="#7c3aed" stroke-width="4.5" stroke-linecap="round"/><path transform="translate(197 106) rotate(10)" d="M-8 -10 L8 10 M8 -10 L-8 10" stroke="#7c3aed" stroke-width="4.5" stroke-linecap="round"/><path transform="translate(181 102) rotate(-40)" d="M-8 -10 L8 10 M8 -10 L-8 10" stroke="#7c3aed" stroke-width="4.5" stroke-linecap="round"/><path transform="translate(209 90) rotate(80)" d="M-8 -10 L8 10 M8 -10 L-8 10" stroke="#7c3aed" stroke-width="4.5" stroke-linecap="round"/><g fill="#fff7ed" stroke="#c2410c" stroke-width="3.5"><circle cx="340" cy="64" r="33" /><circle cx="340" cy="120" r="33" /></g><g fill="#fff7ed"><circle cx="340" cy="64" r="31.5" /><circle cx="340" cy="120" r="31.5" /></g><circle cx="340" cy="64" r="17" fill="#e0e7ff" stroke="#4338ca" stroke-width="2.5"/><circle cx="340" cy="120" r="17" fill="#e0e7ff" stroke="#4338ca" stroke-width="2.5"/><ellipse cx="475" cy="92" rx="56" ry="60" fill="#fff7ed" stroke="#c2410c" stroke-width="3.5"/><line x1="475" y1="36" x2="448" y2="68" stroke="#94a3b8" stroke-width="1.2"/><line x1="475" y1="148" x2="448" y2="116" stroke="#94a3b8" stroke-width="1.2"/><path d="M448 68 l6 11 M448 68 l-6 11" stroke="#7c3aed" stroke-width="4.5" stroke-linecap="round"/><path d="M448 116 l6 -11 M448 116 l-6 -11" stroke="#7c3aed" stroke-width="4.5" stroke-linecap="round"/><line x1="475" y1="36" x2="466" y2="68" stroke="#94a3b8" stroke-width="1.2"/><line x1="475" y1="148" x2="466" y2="116" stroke="#94a3b8" stroke-width="1.2"/><path d="M466 68 l6 11 M466 68 l-6 11" stroke="#7c3aed" stroke-width="4.5" stroke-linecap="round"/><path d="M466 116 l6 -11 M466 116 l-6 -11" stroke="#7c3aed" stroke-width="4.5" stroke-linecap="round"/><line x1="475" y1="36" x2="484" y2="68" stroke="#94a3b8" stroke-width="1.2"/><line x1="475" y1="148" x2="484" y2="116" stroke="#94a3b8" stroke-width="1.2"/><path d="M484 68 l6 11 M484 68 l-6 11" stroke="#7c3aed" stroke-width="4.5" stroke-linecap="round"/><path d="M484 116 l6 -11 M484 116 l-6 -11" stroke="#7c3aed" stroke-width="4.5" stroke-linecap="round"/><line x1="475" y1="36" x2="502" y2="68" stroke="#94a3b8" stroke-width="1.2"/><line x1="475" y1="148" x2="502" y2="116" stroke="#94a3b8" stroke-width="1.2"/><path d="M502 68 l6 11 M502 68 l-6 11" stroke="#7c3aed" stroke-width="4.5" stroke-linecap="round"/><path d="M502 116 l6 -11 M502 116 l-6 -11" stroke="#7c3aed" stroke-width="4.5" stroke-linecap="round"/><g class="tg"><circle cx="70" cy="178" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="70" y="178.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">P</text></g><g class="tg"><circle cx="205" cy="178" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="205" y="178.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">R</text></g><g class="tg"><circle cx="340" cy="178" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="340" y="178.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">Q</text></g><g class="tg"><circle cx="475" cy="178" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="475" y="178.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">S</text></g></svg>', 'The cell labelled R has condensing chromosomes and a breaking-down nuclear envelope (prophase); P has chromosomes lined up at the equator (metaphase); S shows chromatids moving to opposite poles (anaphase); Q shows two daughter nuclei with the cell pinching (telophase).', 'A');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'R → P → S → Q');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'P → R → Q → S');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'R → S → P → Q');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Q → S → R → P');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 5, 'Botany', 'Calvin Cycle (Flow Diagram)', 'Medium', 'The diagram shows the three phases of the Calvin cycle. What is the missing phase marked "?"', 1, '<svg viewBox="0 0 580 430" xmlns="http://www.w3.org/2000/svg"><rect width="580" height="430" fill="#f8fafc" rx="12"/><text x="290" y="26" text-anchor="middle" font-family="Arial" font-size="15" font-weight="700" fill="#0f172a">Calvin cycle (C3 plants)</text><line x1="319.4" y1="127.0" x2="441.4" y2="259.6" stroke="#475569" stroke-width="2.6"/><polygon points="446.8,265.5 433.6,260.0 442.4,251.9" fill="#475569"/><line x1="397.2" y1="297.5" x2="157.8" y2="297.5" stroke="#475569" stroke-width="2.6"/><polygon points="149.8,297.5 162.8,291.5 162.8,303.5" fill="#475569"/><line x1="125.9" y1="273.5" x2="255.2" y2="132.9" stroke="#475569" stroke-width="2.6"/><polygon points="260.6,127.0 256.2,140.6 247.4,132.5" fill="#475569"/><rect x="222.4" y="66.0" width="135.2" height="58" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="290.0" y="86.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Carboxylation</text><text x="290.0" y="103.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">of RuBP</text><rect x="400.2" y="268.5" width="152.0" height="58" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="476.2" y="289.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Reduction using</text><text x="476.2" y="306.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">ATP and NADPH</text><rect x="60.8" y="276.5" width="86.0" height="42" rx="10" fill="#fef9c3" stroke="#ca8a04" stroke-width="2.5"/><text x="103.8" y="297.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="22" font-weight="700" fill="#0f172a">?</text></svg>', 'The Calvin cycle has three phases: carboxylation (CO_2 + RuBP, catalysed by RuBisCO), reduction (using ATP and NADPH to make triose phosphate) and regeneration of the CO_2 acceptor RuBP, which keeps the cycle going.', 'D');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Photolysis of water');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Oxidative decarboxylation');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'Glycolysis');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Regeneration of RuBP');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 6, 'Botany', 'Light and Photosynthesis (Graph)', 'Medium', 'The graph shows how the rate of photosynthesis of a plant changes with light intensity. Beyond what light intensity does the rate stop increasing?', 1, '<svg viewBox="0 0 540 320" xmlns="http://www.w3.org/2000/svg"><rect width="540" height="320" fill="#f8fafc" rx="12"/><text x="270" y="26" text-anchor="middle" font-family="Arial" font-size="15" font-weight="700" fill="#0f172a">Rate of photosynthesis at different light intensities</text><line x1="78" y1="256.0" x2="516" y2="256.0" stroke="#64748b" stroke-width="1"/><text x="71" y="256.0" text-anchor="end" dominant-baseline="central" font-family="Arial" font-size="11" fill="#475569">0</text><line x1="78" y1="207.5" x2="516" y2="207.5" stroke="#e2e8f0" stroke-width="1"/><text x="71" y="207.5" text-anchor="end" dominant-baseline="central" font-family="Arial" font-size="11" fill="#475569">5</text><line x1="78" y1="159.0" x2="516" y2="159.0" stroke="#e2e8f0" stroke-width="1"/><text x="71" y="159.0" text-anchor="end" dominant-baseline="central" font-family="Arial" font-size="11" fill="#475569">10</text><line x1="78" y1="110.5" x2="516" y2="110.5" stroke="#e2e8f0" stroke-width="1"/><text x="71" y="110.5" text-anchor="end" dominant-baseline="central" font-family="Arial" font-size="11" fill="#475569">15</text><line x1="78" y1="62.0" x2="516" y2="62.0" stroke="#e2e8f0" stroke-width="1"/><text x="71" y="62.0" text-anchor="end" dominant-baseline="central" font-family="Arial" font-size="11" fill="#475569">20</text><line x1="78" y1="62" x2="78" y2="256" stroke="#64748b" stroke-width="1.6"/><text x="109.3" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">0</text><text x="171.9" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">10</text><text x="234.4" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">20</text><text x="297.0" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">30</text><text x="359.6" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">40</text><text x="422.1" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">50</text><text x="484.7" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">60</text><polyline points="109.3,256.0 171.9,197.8 234.4,139.6 297.0,81.4 359.6,62.0 422.1,62.0 484.7,62.0" fill="none" stroke="#dc2626" stroke-width="3" stroke-linejoin="round"/><circle cx="109.3" cy="256.0" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="109.3" y="247.0" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">0</text><circle cx="171.9" cy="197.8" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="171.9" y="188.8" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">6</text><circle cx="234.4" cy="139.6" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="234.4" y="130.6" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">12</text><circle cx="297.0" cy="81.4" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="297.0" y="72.4" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">18</text><circle cx="359.6" cy="62.0" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="359.6" y="53.0" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">20</text><circle cx="422.1" cy="62.0" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="422.1" y="53.0" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">20</text><circle cx="484.7" cy="62.0" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="484.7" y="53.0" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">20</text><text x="297" y="308" text-anchor="middle" font-family="Arial" font-size="12" font-weight="700" fill="#475569">Light intensity (kilolux)</text><text transform="translate(16 159) rotate(-90)" text-anchor="middle" font-family="Arial" font-size="12" font-weight="700" fill="#475569">CO2 fixed (units)</text></svg>', 'The rate rises in a straight line up to 40 kilolux and is then constant at 20 units. Beyond this light saturation point another factor (CO_2 concentration or temperature) becomes limiting.', 'A');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '40 kilolux');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '20 kilolux');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '30 kilolux');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '60 kilolux');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 7, 'Botany', 'Microsporangia and Anther', 'Medium', 'A typical anther of an angiosperm flower is bilobed and each lobe has two chambers. How many microsporangia (pollen sacs) does it contain?', 0, NULL, 'A typical anther is bilobed and dithecous: each lobe has two theca, so there are four microsporangia, in which pollen grains develop from microspore mother cells.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '2');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '4');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '6');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '8');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 8, 'Botany', 'Cytokinesis in Plants', 'Medium', 'After telophase, cytokinesis in a plant cell takes place by:', 0, NULL, 'Plant cells have a rigid wall, so cytokinesis occurs centrifugally by the cell plate: Golgi vesicles fuse at the equator to form a new middle lamella and wall. Cleavage furrow formation is typical of animal cells.', 'C');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Formation of a cleavage furrow');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Budding');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'Formation of a cell plate');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Fragmentation');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 9, 'Botany', 'Double Fertilisation', 'Medium', 'In the double fertilisation of an angiosperm, the triploid primary endosperm nucleus (PEN) is formed by the fusion of:', 0, NULL, 'One sperm fuses with the egg (syngamy, 2n zygote) and the second sperm fuses with the two polar nuclei of the central cell (triple fusion), giving the triploid (3n) PEN that develops into the endosperm.', 'D');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'One male gamete and the egg cell');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Two male gametes and the egg cell');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'One male gamete and one synergid');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'One male gamete and the two polar nuclei');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 10, 'Botany', 'C4 Photosynthesis', 'Medium', 'Kranz anatomy, with large chloroplast-containing bundle sheath cells arranged in a wreath around the vascular bundles, is characteristic of:', 0, NULL, 'C4 plants (maize, sugarcane, sorghum) fix CO_2 first into oxaloacetate (a 4-carbon acid) in mesophyll cells, then release it in the bundle sheath cells where the Calvin cycle runs. The wreath-like bundle sheath is called Kranz anatomy.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'C3 plants such as wheat');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'C4 plants such as maize');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'CAM plants such as pineapple');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Hydrophytes such as Hydrilla');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 11, 'Zoology', 'Golgi Apparatus (Diagram)', 'Easy', 'The stack of flattened, membrane-bound cisternae labelled A in this animal cell is mainly concerned with:', 1, '<svg viewBox="0 0 480 295" xmlns="http://www.w3.org/2000/svg"><rect width="480" height="295" fill="#fcf8fb" rx="12"/><g transform="translate(20 0)"><ellipse cx="220" cy="145" rx="185" ry="118" fill="#edfff4" stroke="#0cc223" stroke-width="4"/><circle cx="190" cy="135" r="50" fill="#ffe0ec" stroke="#ca3845" stroke-width="3"/><circle cx="190" cy="135" r="44" fill="none" stroke="#f881a0" stroke-width="1.5" stroke-dasharray="3 3"/><circle cx="200" cy="128" r="14" fill="#ca3845"/><path d="M162 152 q8 -10 16 0 t16 0 t16 0" fill="none" stroke="#f1637e" stroke-width="1.7"/><g transform="translate(310 92) rotate(-22) scale(1)"><ellipse rx="34" ry="17" fill="#8afdd3" stroke="#09b436" stroke-width="2.5"/><path d="M-24 0 l6 -10 l6 20 l6 -20 l6 20 l6 -20 l6 20 l6 -10" fill="none" stroke="#09b436" stroke-width="1.7"/></g><g transform="translate(92 178) rotate(18) scale(0.8)"><ellipse rx="34" ry="17" fill="#8afdd3" stroke="#09b436" stroke-width="2.5"/><path d="M-24 0 l6 -10 l6 20 l6 -20 l6 20 l6 -20 l6 20 l6 -10" fill="none" stroke="#09b436" stroke-width="1.7"/></g><path d="M255 160 q12 -8 24 0 t24 0 t24 0 t24 0" fill="none" stroke="#5d0f76" stroke-width="3.5" stroke-linecap="round"/><circle cx="262" cy="153" r="2.3" fill="#5d0f76"/><circle cx="286" cy="153" r="2.3" fill="#5d0f76"/><circle cx="310" cy="153" r="2.3" fill="#5d0f76"/><circle cx="334" cy="153" r="2.3" fill="#5d0f76"/><path d="M255 173 q12 -8 24 0 t24 0 t24 0 t24 0" fill="none" stroke="#5d0f76" stroke-width="3.5" stroke-linecap="round"/><circle cx="262" cy="166" r="2.3" fill="#5d0f76"/><circle cx="286" cy="166" r="2.3" fill="#5d0f76"/><circle cx="310" cy="166" r="2.3" fill="#5d0f76"/><circle cx="334" 