INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Synthesis of ATP');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'Photosynthesis');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Digestion of worn-out organelles');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 12, 'Zoology', 'Mitochondrion (Diagram)', 'Medium', 'ATP synthase and the electron transport chain are located in the membrane labelled C of this mitochondrion. Which membrane is it?', 1, '<svg viewBox="0 0 480 290" xmlns="http://www.w3.org/2000/svg"><rect width="480" height="290" fill="#fcf8fb" rx="12"/><ellipse cx="240" cy="140" rx="195" ry="104" fill="#8afdd3" stroke="#09b436" stroke-width="4.5"/><ellipse cx="240" cy="140" rx="172" ry="82" fill="#c7feea" stroke="#09b436" stroke-width="3.5"/><path d="M124 77.0 V121.0 a6 6 0 0 0 12 0 V77.0" fill="none" stroke="#09b436" stroke-width="3.2"/><path d="M174 216.8 V172.8 a6 6 0 0 1 12 0 V216.8" fill="none" stroke="#09b436" stroke-width="3.2"/><path d="M224 58.1 V102.1 a6 6 0 0 0 12 0 V58.1" fill="none" stroke="#09b436" stroke-width="3.2"/><path d="M274 219.8 V175.8 a6 6 0 0 1 12 0 V219.8" fill="none" stroke="#09b436" stroke-width="3.2"/><path d="M324 70.1 V114.1 a6 6 0 0 0 12 0 V70.1" fill="none" stroke="#09b436" stroke-width="3.2"/><circle cx="240" cy="140" r="14" fill="none" stroke="#ca3845" stroke-width="3.2"/><circle cx="205" cy="150" r="2.8" fill="#0f7824"/><circle cx="270" cy="125" r="2.8" fill="#0f7824"/><circle cx="300" cy="160" r="2.8" fill="#0f7824"/><circle cx="175" cy="118" r="2.8" fill="#0f7824"/><circle cx="262" cy="168" r="2.8" fill="#0f7824"/><g class="tg"><line x1="80" y1="80" x2="30" y2="34" stroke="#334155" stroke-width="1.5"/><circle cx="80" cy="80" r="3" fill="#334155"/></g><g class="tg"><circle cx="30" cy="34" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="30" y="34.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">B</text></g><g class="tg"><line x1="91" y1="181" x2="32" y2="246" stroke="#334155" stroke-width="1.5"/><circle cx="91" cy="181" r="3" fill="#334155"/></g><g class="tg"><circle cx="32" cy="246" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="32" y="246.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">C</text></g><g class="tg"><line x1="230" y1="84" x2="332" y2="22" stroke="#334155" stroke-width="1.5"/><circle cx="230" cy="84" r="3" fill="#334155"/></g><g class="tg"><circle cx="332" cy="22" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="332" y="22.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">E</text></g><g class="tg"><line x1="300" y1="138" x2="448" y2="190" stroke="#334155" stroke-width="1.5"/><circle cx="300" cy="138" r="3" fill="#334155"/></g><g class="tg"><circle cx="448" cy="190" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="448" y="190.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">F</text></g><g class="tg"><line x1="399" y1="94" x2="452" y2="56" stroke="#334155" stroke-width="1.5"/><circle cx="399" cy="94" r="3" fill="#334155"/></g><g class="tg"><circle cx="452" cy="56" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="452" y="56.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">D</text></g><g class="tg"><line x1="240" y1="154" x2="240" y2="270" stroke="#334155" stroke-width="1.5"/><circle cx="240" cy="154" r="3" fill="#334155"/></g><g class="tg"><circle cx="240" cy="270" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="240" y="270.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">A</text></g></svg>', 'The inner mitochondrial membrane is folded into cristae, which greatly increase its surface area. It carries the electron transport chain and ATP synthase (F_0F_1 particles), where oxidative phosphorylation makes ATP.', 'D');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Outer membrane');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Plasma membrane');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'Nuclear envelope');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Inner membrane');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 13, 'Zoology', 'Human Heart (Diagram)', 'Easy', 'The large vessel labelled C arises from the left ventricle. It carries:', 1, '<svg viewBox="0 0 460 312" xmlns="http://www.w3.org/2000/svg"><rect width="460" height="312" fill="#f8fafc" rx="12"/><path d="M135 125 V52" stroke="#1d4ed8" stroke-width="22" stroke-linecap="butt" fill="none"/><path d="M135 125 V52" stroke="#93c5fd" stroke-width="14" fill="none"/><path d="M222 192 V84 M222 84 q-8 -24 -52 -28 M222 84 q8 -26 50 -30" stroke="#1d4ed8" stroke-width="18" fill="none" stroke-linecap="round"/><path d="M222 192 V84 M222 84 q-8 -24 -52 -28 M222 84 q8 -26 50 -30" stroke="#93c5fd" stroke-width="11" fill="none" stroke-linecap="round"/><path d="M300 112 H362 M300 146 H362" stroke="#b91c1c" stroke-width="16" fill="none"/><path d="M300 112 H362 M300 146 H362" stroke="#fca5a5" stroke-width="9" fill="none"/><rect x="112" y="108" width="92" height="84" rx="16" fill="#bfdbfe" stroke="#1d4ed8" stroke-width="3"/><rect x="262" y="98" width="92" height="84" rx="16" fill="#fecaca" stroke="#b91c1c" stroke-width="3"/><path d="M112 196 H214 V262 Q170 306 112 252 Z" fill="#bfdbfe" stroke="#1d4ed8" stroke-width="3"/><path d="M230 188 H352 V250 Q310 318 238 280 Q226 270 230 188 Z" fill="#fecaca" stroke="#b91c1c" stroke-width="3"/><path d="M246 190 V92 Q246 40 300 40 Q372 40 372 104 V210" stroke="#b91c1c" stroke-width="18" fill="none" stroke-linecap="round"/><path d="M246 190 V92 Q246 40 300 40 Q372 40 372 104 V210" stroke="#fca5a5" stroke-width="11" fill="none" stroke-linecap="round"/><path d="M124 194 l14 17 M198 194 l-14 17" stroke="#334155" stroke-width="3.5" stroke-linecap="round"/><path d="M276 184 l13 17 M340 184 l-13 17" stroke="#334155" stroke-width="3.5" stroke-linecap="round"/><g font-family="Arial" font-size="11" fill="#334155"><rect x="22" y="288" width="10" height="10" fill="#bfdbfe" stroke="#1d4ed8"/><text x="38" y="297">deoxygenated</text><rect x="118" y="288" width="10" height="10" fill="#fecaca" stroke="#b91c1c"/><text x="134" y="297">oxygenated</text></g><g class="tg"><line x1="130" y1="150" x2="52" y2="150" stroke="#334155" stroke-width="1.5"/><circle cx="130" cy="150" r="3" fill="#334155"/></g><g class="tg"><circle cx="52" cy="150" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="52" y="150.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">A</text></g><g class="tg"><line x1="320" y1="238" x2="420" y2="262" stroke="#334155" stroke-width="1.5"/><circle cx="320" cy="238" r="3" fill="#334155"/></g><g class="tg"><circle cx="420" cy="262" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="420" y="262.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">B</text></g><g class="tg"><line x1="372" y1="100" x2="420" y2="70" stroke="#334155" stroke-width="1.5"/><circle cx="372" cy="100" r="3" fill="#334155"/></g><g class="tg"><circle cx="420" cy="70" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="420" y="70.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">C</text></g><g class="tg"><line x1="205" y1="70" x2="190" y2="22" stroke="#334155" stroke-width="1.5"/><circle cx="205" cy="70" r="3" fill="#334155"/></g><g class="tg"><circle cx="190" cy="22" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="190" y="22.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">D</text></g><g class="tg"><line x1="340" y1="198" x2="428" y2="190" stroke="#334155" stroke-width="1.5"/><circle cx="340" cy="198" r="3" fill="#334155"/></g><g class="tg"><circle cx="428" cy="190" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="428" y="190.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">E</text></g><g class="tg"><line x1="135" y1="62" x2="76" y2="36" stroke="#334155" stroke-width="1.5"/><circle cx="135" cy="62" r="3" fill="#334155"/></g><g class="tg"><circle cx="76" cy="36" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="76" y="36.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">F</text></g></svg>', 'The aorta distributes oxygenated blood pumped by the left ventricle to the whole body (systemic circulation). Pulmonary veins bring oxygenated blood from the lungs, and venae cavae bring deoxygenated blood from the body.', 'D');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Deoxygenated blood to the lungs');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Oxygenated blood from the lungs');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'Deoxygenated blood from the body');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Oxygenated blood to the body');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 14, 'Zoology', 'Pulmonary Circulation (Flow Diagram)', 'Medium', 'The flow diagram shows the path of blood from the right atrium through the lungs. Which chamber is missing at "?"', 1, '<svg viewBox="0 0 550 340" xmlns="http://www.w3.org/2000/svg"><rect width="550" height="340" fill="#f8fafc" rx="12"/><text x="290" y="26" text-anchor="middle" font-family="Arial" font-size="15" font-weight="700" fill="#0f172a">Path of blood through the heart and lungs</text><line x1="171.4" y1="90.0" x2="221.0" y2="90.0" stroke="#475569" stroke-width="2.6"/><polygon points="229.0,90.0 216.0,96.0 216.0,84.0" fill="#475569"/><line x1="321.0" y1="90.0" x2="383.2" y2="90.0" stroke="#475569" stroke-width="2.6"/><polygon points="391.2,90.0 378.2,96.0 378.2,84.0" fill="#475569"/><path d="M445.0 119.0 V150.0 H105.0 V179.0" fill="none" stroke="#475569" stroke-width="2.6"/><polygon points="105.0,189.0 99.0,176.0 111.0,176.0" fill="#475569"/><line x1="151.0" y1="210.0" x2="204.8" y2="210.0" stroke="#475569" stroke-width="2.6"/><polygon points="212.8,210.0 199.8,216.0 199.8,204.0" fill="#475569"/><line x1="337.2" y1="210.0" x2="362.2" y2="210.0" stroke="#475569" stroke-width="2.6"/><polygon points="370.2,210.0 357.2,216.0 357.2,204.0" fill="#475569"/><rect x="41.6" y="69.0" width="126.8" height="42" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="105.0" y="90.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Right atrium</text><rect x="232.0" y="69.0" width="86.0" height="42" rx="10" fill="#fef9c3" stroke="#ca8a04" stroke-width="2.5"/><text x="275.0" y="90.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="22" font-weight="700" fill="#0f172a">?</text><rect x="394.2" y="61.0" width="101.6" height="58" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="445.0" y="81.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Pulmonary</text><text x="445.0" y="98.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">artery</text><rect x="62.0" y="189.0" width="86.0" height="42" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="105.0" y="210.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Lungs</text><rect x="215.8" y="189.0" width="118.4" height="42" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="275.0" y="210.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Left atrium</text><rect x="373.2" y="189.0" width="143.6" height="42" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="445.0" y="210.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Left ventricle</text></svg>', 'Deoxygenated blood passes from the right atrium through the tricuspid valve into the right ventricle, which pumps it through the pulmonary artery to the lungs. Oxygenated blood returns by the pulmonary veins to the left atrium.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Left ventricle');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Right ventricle');
