INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 15, 'Zoology', 'Neuron and Nerve Impulse (Diagram)', 'Medium', 'In a myelinated axon the impulse appears to jump between the gaps labelled A. This type of conduction is called:', 1, '<svg viewBox="0 0 530 240" xmlns="http://www.w3.org/2000/svg"><rect width="530" height="240" fill="#f9fcf8" rx="12"/><path d="M84 100 L48 70 L22 60 M48 70 L38 38" fill="none" stroke="#8c09b4" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><path d="M80 128 L38 132 L14 120 M38 132 L18 150" fill="none" stroke="#8c09b4" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><path d="M92 148 L62 182 L36 192 M62 182 L58 210" fill="none" stroke="#8c09b4" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><circle cx="112" cy="124" r="36" fill="#fd8aee" stroke="#8c09b4" stroke-width="3.5"/><circle cx="112" cy="124" r="15" fill="#c7fece" stroke="#38ca74" stroke-width="2.5"/><circle cx="116" cy="121" r="4.5" fill="#38ca74"/><path d="M144 112 L176 120 V128 L144 136 Z" fill="#fd8aee" stroke="#8c09b4" stroke-width="3"/><line x1="176" y1="124" x2="410" y2="124" stroke="#8c09b4" stroke-width="4.5"/><rect x="190" y="110" width="52" height="28" rx="12" fill="#e3f0e2" stroke="#678b64" stroke-width="2.5"/><path d="M208 118 V130 M216 118 V130 M224 118 V130" stroke="#97b894" stroke-width="2"/><rect x="252" y="110" width="52" height="28" rx="12" fill="#e3f0e2" stroke="#678b64" stroke-width="2.5"/><path d="M270 118 V130 M278 118 V130 M286 118 V130" stroke="#97b894" stroke-width="2"/><rect x="314" y="110" width="52" height="28" rx="12" fill="#e3f0e2" stroke="#678b64" stroke-width="2.5"/><path d="M332 118 V130 M340 118 V130 M348 118 V130" stroke="#97b894" stroke-width="2"/><path d="M410 124 L446 86" stroke="#8c09b4" stroke-width="3.5" fill="none"/><circle cx="455" cy="86" r="9" fill="#c2a5fc" stroke="#501cb9" stroke-width="2.5"/><path d="M410 124 L457 124" stroke="#8c09b4" stroke-width="3.5" fill="none"/><circle cx="466" cy="124" r="9" fill="#c2a5fc" stroke="#501cb9" stroke-width="2.5"/><path d="M410 124 L446 162" stroke="#8c09b4" stroke-width="3.5" fill="none"/><circle cx="455" cy="162" r="9" fill="#c2a5fc" stroke="#501cb9" stroke-width="2.5"/><g class="tg"><line x1="33" y1="62" x2="40" y2="24" stroke="#334155" stroke-width="1.5"/><circle cx="33" cy="62" r="3" fill="#334155"/></g><g class="tg"><circle cx="40" cy="24" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="40" y="24.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">B</text></g><g class="tg"><line x1="106" y1="128" x2="90" y2="218" stroke="#334155" stroke-width="1.5"/><circle cx="106" cy="128" r="3" fill="#334155"/></g><g class="tg"><circle cx="90" cy="218" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="90" y="218.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">D</text></g><g class="tg"><line x1="277" y1="112" x2="277" y2="46" stroke="#334155" stroke-width="1.5"/><circle cx="277" cy="112" r="3" fill="#334155"/></g><g class="tg"><circle cx="277" cy="46" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="277" y="46.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">C</text></g><g class="tg"><line x1="247" y1="125" x2="247" y2="205" stroke="#334155" stroke-width="1.5"/><circle cx="247" cy="125" r="3" fill="#334155"/></g><g class="tg"><circle cx="247" cy="205" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="247" y="205.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">A</text></g><g class="tg"><line x1="462" y1="90" x2="500" y2="70" stroke="#334155" stroke-width="1.5"/><circle cx="462" cy="90" r="3" fill="#334155"/></g><g class="tg"><circle cx="500" cy="70" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="500" y="70.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">F</text></g><g class="tg"><line x1="160" y1="117" x2="160" y2="66" stroke="#334155" stroke-width="1.5"/><circle cx="160" cy="117" r="3" fill="#334155"/></g><g class="tg"><circle cx="160" cy="66" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="160" y="66.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">E</text></g></svg>', 'Myelin insulates the axon, so depolarisation happens only at the nodes of Ranvier. The impulse jumps from node to node (saltatory conduction), which is faster and uses less energy than continuous conduction in unmyelinated fibres.', 'B');
