INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 16, 'Zoology', 'Synaptic Transmission (Diagram)', 'Hard', 'Neurotransmitters are stored in the synaptic vesicles (labelled E). Influx of which ion into the axon terminal triggers the release of the vesicles?', 1, '<svg viewBox="0 0 540 300" xmlns="http://www.w3.org/2000/svg"><rect width="540" height="300" fill="#f8fcfb" rx="12"/><rect x="250" y="40" width="50" height="220" fill="#f1f9f6"/><path d="M300 40 H500 Q520 40 520 62 V238 Q520 260 500 260 H300 Z" fill="#c7fefc" stroke="#38a7ca" stroke-width="3"/><path d="M10 100 Q10 40 70 40 H200 Q250 40 250 90 V210 Q250 260 200 260 H70 Q10 260 10 200 Z" fill="#fd8a8e" stroke="#b4094e" stroke-width="3"/><g transform="translate(88 208) rotate(8) scale(0.9)"><ellipse rx="34" ry="17" fill="#fd8a8e" stroke="#b4094e" stroke-width="2.5"/><path d="M-24 0 l6 -10 l6 20 l6 -20 l6 20 l6 -20 l6 20 l6 -10" fill="none" stroke="#b4094e" stroke-width="1.7"/></g><circle cx="150" cy="95" r="14" fill="#fecaf5" stroke="#b91c9f" stroke-width="2"/><circle cx="145" cy="92" r="2.5" fill="#b91c9f"/><circle cx="154" cy="91" r="2.5" fill="#b91c9f"/><circle cx="150" cy="100" r="2.5" fill="#b91c9f"/><circle cx="112" cy="142" r="14" fill="#fecaf5" stroke="#b91c9f" stroke-width="2"/><circle cx="107" cy="139" r="2.5" fill="#b91c9f"/><circle cx="116" cy="138" r="2.5" fill="#b91c9f"/><circle cx="112" cy="147" r="2.5" fill="#b91c9f"/><circle cx="192" cy="150" r="14" fill="#fecaf5" stroke="#b91c9f" stroke-width="2"/><circle cx="187" cy="147" r="2.5" fill="#b91c9f"/><circle cx="196" cy="146" r="2.5" fill="#b91c9f"/><circle cx="192" cy="155" r="2.5" fill="#b91c9f"/><circle cx="168" cy="205" r="14" fill="#fecaf5" stroke="#b91c9f" stroke-width="2"/><circle cx="163" cy="202" r="2.5" fill="#b91c9f"/><circle cx="172" cy="201" r="2.5" fill="#b91c9f"/><circle cx="168" cy="210" r="2.5" fill="#b91c9f"/><circle cx="208" cy="98" r="14" fill="#fecaf5" stroke="#b91c9f" stroke-width="2"/><circle cx="203" cy="95" r="2.5" fill="#b91c9f"/><circle cx="212" cy="94" r="2.5" fill="#b91c9f"/><circle cx="208" cy="103" r="2.5" fill="#b91c9f"/><circle cx="246" cy="165" r="13" fill="#fecaf5" stroke="#b91c9f" stroke-width="2"/><circle cx="264" cy="150" r="3.2" fill="#b91c9f"/><circle cx="277" cy="166" r="3.2" fill="#b91c9f"/><circle cx="270" cy="184" r="3.2" fill="#b91c9f"/><circle cx="284" cy="150" r="3.2" fill="#b91c9f"/><circle cx="286" cy="182" r="3.2" fill="#b91c9f"/><circle cx="262" cy="168" r="3.2" fill="#b91c9f"/><path d="M300 88 H288 L277 78 M288 88 L277 98" fill="none" stroke="#468015" stroke-width="4.5" stroke-linecap="round"/><path d="M300 138 H288 L277 128 M288 138 L277 148" fill="none" stroke="#468015" stroke-width="4.5" stroke-linecap="round"/><path d="M300 190 H288 L277 180 M288 190 L277 200" fill="none" stroke="#468015" stroke-width="4.5" stroke-linecap="round"/><path d="M300 236 H288 L277 226 M288 236 L277 246" fill="none" stroke="#468015" stroke-width="4.5" stroke-linecap="round"/><g class="tg"><line x1="150" y1="81" x2="150" y2="20" stroke="#334155" stroke-width="1.5"/><circle cx="150" cy="81" r="3" fill="#334155"/></g><g class="tg"><circle cx="150" cy="20" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="150" y="20.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">E</text></g><g class="tg"><line x1="272" y1="228" x2="270" y2="284" stroke="#334155" stroke-width="1.5"/><circle cx="272" cy="228" r="3" fill="#334155"/></g><g class="tg"><circle cx="270" cy="284" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="270" y="284.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">B</text></g><g class="tg"><line x1="280" y1="190" x2="410" y2="284" stroke="#334155" stroke-width="1.5"/><circle cx="280" cy="190" r="3" fill="#334155"/></g><g class="tg"><circle cx="410" cy="284" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="410" y="284.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">C</text></g><g class="tg"><line x1="60" y1="70" x2="52" y2="20" stroke="#334155" stroke-width="1.5"/><circle cx="60" cy="70" r="3" fill="#334155"/></g><g class="tg"><circle cx="52" cy="20" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="52" y="20.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">D</text></g><g class="tg"><line x1="90" y1="212" x2="40" y2="284" stroke="#334155" stroke-width="1.5"/><circle cx="90" cy="212" r="3" fill="#334155"/></g><g class="tg"><circle cx="40" cy="284" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="40" y="284.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">A</text></g><g class="tg"><line x1="440" y1="110" x2="480" y2="20" stroke="#334155" stroke-width="1.5"/><circle cx="440" cy="110" r="3" fill="#334155"/></g><g class="tg"><circle cx="480" cy="20" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="480" y="20.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">F</text></g></svg>', 'When an action potential reaches the axon terminal, voltage-gated Ca^{2+} channels open. The Ca^{2+} influx makes the synaptic vesicles fuse with the presynaptic membrane and release the neurotransmitter into the synaptic cleft (B) by exocytosis.', 'D');
