INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 17, 'Zoology', 'Nephron: Reabsorption (Diagram)', 'Medium', 'Selective reabsorption of nearly all the glucose and amino acids from the glomerular filtrate takes place in the part labelled B. Which part is it?', 1, '<svg viewBox="0 0 500 340" xmlns="http://www.w3.org/2000/svg"><rect width="500" height="340" fill="#f8fafc" rx="12"/><rect x="0" y="0" width="500" height="196" rx="12" fill="#fdf2f8"/><rect x="0" y="196" width="500" height="144" fill="#fee2e2"/><g font-family="Arial" font-size="12" font-weight="700" fill="#9d174d"><text x="372" y="22">CORTEX</text><text x="372" y="218">MEDULLA</text></g><path d="M30 60 H64 M30 92 H64" stroke="#dc2626" stroke-width="5" fill="none"/><path d="M96 100 V104" fill="none" stroke="#0369a1" stroke-linecap="round" stroke-linejoin="round" stroke-width="9"/><circle cx="96" cy="80" r="32" fill="#fef3c7" stroke="#b45309" stroke-width="4"/><path d="M78 82 q8 -22 18 -4 t16 -2 q-6 24 -22 12 t-12 -6" fill="none" stroke="#dc2626" stroke-width="3.5" stroke-linecap="round"/><path d="M96 112 q-16 12 0 24 t0 24 t0 24 t0 24" fill="none" stroke="#0369a1" stroke-linecap="round" stroke-linejoin="round" stroke-width="9"/><path d="M96 208 V296 Q128 336 160 296 V208" fill="none" stroke="#0369a1" stroke-linecap="round" stroke-linejoin="round" stroke-width="8"/><path d="M160 208 V196 q16 -12 0 -24 t0 -24 t0 -24 V112 H336" fill="none" stroke="#0369a1" stroke-linecap="round" stroke-linejoin="round" stroke-width="9"/><path d="M336 40 V320" stroke="#0284c7" stroke-width="17" stroke-linecap="round" fill="none"/><path d="M336 40 V320" stroke="#7dd3fc" stroke-width="10" stroke-linecap="round" fill="none"/><g class="tg"><line x1="82" y1="66" x2="40" y2="24" stroke="#334155" stroke-width="1.5"/><circle cx="82" cy="66" r="3" fill="#334155"/></g><g class="tg"><circle cx="40" cy="24" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="40" y="24.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">A</text></g><g class="tg"><line x1="90" y1="150" x2="44" y2="150" stroke="#334155" stroke-width="1.5"/><circle cx="90" cy="150" r="3" fill="#334155"/></g><g class="tg"><circle cx="44" cy="150" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="44" y="150.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">B</text></g><g class="tg"><line x1="100" y1="296" x2="54" y2="300" stroke="#334155" stroke-width="1.5"/><circle cx="100" cy="296" r="3" fill="#334155"/></g><g class="tg"><circle cx="54" cy="300" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="54" y="300.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">C</text></g><g class="tg"><line x1="160" y1="152" x2="218" y2="152" stroke="#334155" stroke-width="1.5"/><circle cx="160" cy="152" r="3" fill="#334155"/></g><g class="tg"><circle cx="218" cy="152" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="218" y="152.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">D</text></g><g class="tg"><line x1="340" y1="230" x2="430" y2="230" stroke="#334155" stroke-width="1.5"/><circle cx="340" cy="230" r="3" fill="#334155"/></g><g class="tg"><circle cx="430" cy="230" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="430" y="230.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">E</text></g></svg>', 'The PCT, lined with brush-border (microvilli) epithelium, reabsorbs nearly all the glucose and amino acids, and about 70 to 80 per cent of the electrolytes and water.', 'C');
