INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 18, 'Zoology', 'Human Eye (Diagram)', 'Easy', 'The light-sensitive layer labelled D at the back of the eye contains the photoreceptors. They are:', 1, '<svg viewBox="0 0 540 310" xmlns="http://www.w3.org/2000/svg"><rect width="540" height="310" fill="#f8fafc" rx="12"/><circle cx="280" cy="150" r="108" fill="#f0f9ff" stroke="#94a3b8" stroke-width="9"/><path d="M330 63.4 A100 100 0 0 1 330 236.6" fill="none" stroke="#dc2626" stroke-width="7"/><path d="M196 88 Q116 150 196 212" fill="rgba(186,230,253,0.55)" stroke="#38bdf8" stroke-width="8" stroke-linecap="round"/><ellipse cx="236" cy="150" rx="16" ry="34" fill="#bae6fd" stroke="#0369a1" stroke-width="3"/><path d="M196 96 L218 100 L214 136 L204 136 Z M196 204 L218 200 L214 164 L204 164 Z" fill="#92400e" stroke="#78350f" stroke-width="2"/><path d="M222 100 L240 120 M222 200 L240 180" stroke="#94a3b8" stroke-width="1.6"/><rect x="384" y="138" width="92" height="24" rx="4" fill="#fde68a" stroke="#b45309" stroke-width="2.5"/><g class="tg"><line x1="160" y1="140" x2="60" y2="50" stroke="#334155" stroke-width="1.5"/><circle cx="160" cy="140" r="3" fill="#334155"/></g><g class="tg"><circle cx="60" cy="50" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="60" y="50.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">A</text></g><g class="tg"><line x1="207" y1="112" x2="150" y2="24" stroke="#334155" stroke-width="1.5"/><circle cx="207" cy="112" r="3" fill="#334155"/></g><g class="tg"><circle cx="150" cy="24" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="150" y="24.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">B</text></g><g class="tg"><line x1="236" y1="168" x2="224" y2="286" stroke="#334155" stroke-width="1.5"/><circle cx="236" cy="168" r="3" fill="#334155"/></g><g class="tg"><circle cx="224" cy="286" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="224" y="286.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">C</text></g><g class="tg"><line x1="366.6" y1="100" x2="470" y2="66" stroke="#334155" stroke-width="1.5"/><circle cx="366.6" cy="100" r="3" fill="#334155"/></g><g class="tg"><circle cx="470" cy="66" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="470" y="66.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">D</text></g><g class="tg"><line x1="440" y1="160" x2="500" y2="210" stroke="#334155" stroke-width="1.5"/><circle cx="440" cy="160" r="3" fill="#334155"/></g><g class="tg"><circle cx="500" cy="210" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="500" y="210.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">E</text></g><g class="tg"><line x1="226" y1="243" x2="130" y2="270" stroke="#334155" stroke-width="1.5"/><circle cx="226" cy="243" r="3" fill="#334155"/></g><g class="tg"><circle cx="130" cy="270" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="130" y="270.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">F</text></g></svg>', 'The retina has rods (dim-light, black and white vision) and cones (bright-light, colour vision). Hair cells are in the cochlea of the ear.', 'C');
