91c1c" stroke-width="2.2"/><text x="340" y="36.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">D</text></g><g class="tg"><line x1="291" y1="238" x2="400" y2="288" stroke="#334155" stroke-width="1.5"/><circle cx="291" cy="238" r="3" fill="#334155"/></g><g class="tg"><circle cx="400" cy="288" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="400" y="288.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">E</text></g><g class="tg"><line x1="124" y1="254" x2="62" y2="288" stroke="#334155" stroke-width="1.5"/><circle cx="124" cy="254" r="3" fill="#334155"/></g><g class="tg"><circle cx="62" cy="288" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="62" y="288.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">F</text></g><g class="tg"><line x1="230" y1="254" x2="230" y2="288" stroke="#334155" stroke-width="1.5"/><circle cx="230" cy="254" r="3" fill="#334155"/></g><g class="tg"><circle cx="230" cy="288" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="230" y="288.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">B</text></g></svg>', 'In the sliding-filament model the thin filaments slide towards the centre. The I band (only thin filaments) and the H zone (only thick filaments) shorten, the Z lines move closer, but the A band (the length of the thick filaments) does not change.', 'A');
