INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 20, 'Zoology', 'Bacteriophage (Diagram)', 'Medium', 'In a T4 bacteriophage the part labelled B contracts after the phage attaches to a bacterium, pushing the core through the cell wall. Which part is this?', 1, '<svg viewBox="0 0 480 340" xmlns="http://www.w3.org/2000/svg"><rect width="480" height="340" fill="#fcfbf8" rx="12"/><polygon points="240,22 292,50 292,114 240,142 188,114 188,50" fill="#998afd" stroke="#0931b4" stroke-width="3.5"/><path d="M214 60 q10 -12 20 0 t20 0 M210 84 q10 -12 20 0 t20 0 M214 108 q10 -12 20 0 t20 0" fill="none" stroke="#8eca38" stroke-width="3" stroke-linecap="round"/><rect x="220" y="142" width="40" height="14" rx="3" fill="#a5dffc" stroke="#1c85b9" stroke-width="2"/><rect x="226" y="156" width="28" height="92" fill="#fde7ba" stroke="#a17003" stroke-width="2.5"/><line x1="226" y1="166" x2="254" y2="166" stroke="#a17003" stroke-width="1.6"/><line x1="226" y1="176" x2="254" y2="176" stroke="#a17003" stroke-width="1.6"/><line x1="226" y1="186" x2="254" y2="186" stroke="#a17003" stroke-width="1.6"/><line x1="226" y1="196" x2="254" y2="196" stroke="#a17003" stroke-width="1.6"/><line x1="226" y1="206" x2="254" y2="206" stroke="#a17003" stroke-width="1.6"/><line x1="226" y1="216" x2="254" y2="216" stroke="#a17003" stroke-width="1.6"/><line x1="226" y1="226" x2="254" y2="226" stroke="#a17003" stroke-width="1.6"/><line x1="226" y1="236" x2="254" y2="236" stroke="#a17003" stroke-width="1.6"/><polygon points="200,248 280,248 294,264 280,280 200,280 186,264" fill="#f7fec7" stroke="#8eca38" stroke-width="3"/><path d="M194 268 L172 318 L142 308" fill="none" stroke="#696647" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/><path d="M190 268 L162 318 L132 308" fill="none" stroke="#696647" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/><path d="M186 268 L152 318 L122 308" fill="none" stroke="#696647" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/><path d="M286 268 L308 318 L338 308" fill="none" stroke="#696647" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/><path d="M290 268 L318 318 L348 308" fill="none" stroke="#696647" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/><path d="M294 268 L328 318 L358 308" fill="none" stroke="#696647" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/><g class="tg"><line x1="190" y1="70" x2="90" y2="40" stroke="#334155" stroke-width="1.5"/><circle cx="190" cy="70" r="3" fill="#334155"/></g><g class="tg"><circle cx="90" cy="40" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="90" y="40.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">E</text></g><g class="tg"><line x1="262" y1="84" x2="400" y2="60" stroke="#334155" stroke-width="1.5"/><circle cx="262" cy="84" r="3" fill="#334155"/></g><g class="tg"><circle cx="400" cy="60" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="400" y="60.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">D</text></g><g class="tg"><line x1="260" y1="149" x2="380" y2="138" stroke="#334155" stroke-width="1.5"/><circle cx="260" cy="149" r="3" fill="#334155"/></g><g class="tg"><circle cx="380" cy="138" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="380" y="138.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">C</text></g><g class="tg"><line x1="254" y1="200" x2="400" y2="205" stroke="#334155" stroke-width="1.5"/><circle cx="254" cy="200" r="3" fill="#334155"/></g><g class="tg"><circle cx="400" cy="205" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="400" y="205.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">B</text></g><g class="tg"><line x1="292" y1="264" x2="400" y2="266" stroke="#334155" stroke-width="1.5"/><circle cx="292" cy="264" r="3" fill="#334155"/></g><g class="tg"><circle cx="400" cy="266" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="400" y="266.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">F</text></g><g class="tg"><line x1="148" y1="306" x2="70" y2="300" stroke="#334155" stroke-width="1.5"/><circle cx="148" cy="306" r="3" fill="#334155"/></g><g class="tg"><circle cx="70" cy="300" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="70" y="300.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">A</text></g></svg>', 'The contractile tail sheath shortens like a spring, driving the hollow core into the host cell so that the DNA from the head is injected. The tail fibres only attach to the receptors on the bacterial surface.', 'C');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Head (capsid)');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Collar');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'Tail sheath');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Tail fibre');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 21, 'Zoology', 'Lysosomes', 'Easy', 'Lysosomes are called ''suicide bags'' because they contain:', 0, NULL, 'Lysosomes hold acid hydrolases (about 40 types, active at acidic pH). If the membrane bursts, these enzymes digest the cell itself, hence the name suicide bags.', 'D');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Chlorophyll');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'DNA polymerase');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'Oxidative phosphorylation enzymes');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Hydrolytic enzymes');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 22, 'Zoology', 'Glomerular Filtration', 'Medium', 'What is the normal glomerular filtration rate (GFR) of a healthy adult?', 0, NULL, 'A healthy adult has a GFR of about 125 mL/min, that is about 180 litres of filtrate per day, of which only about 1.5 litres is excreted as urine because most is reabsorbed.', 'D');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'About 12.5 mL/min');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'About 1250 mL/min');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'About 25 mL/min');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'About 125 mL/min');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 23, 'Zoology', 'Loop of Henle', 'Hard', 'The main role of the loop of Henle and the vasa recta together is to:', 0, NULL, 'The loop of Henle and the vasa recta work as a countercurrent system that builds up a gradient of osmolarity (about 300 mOsm/L in the cortex to about 1200 mOsm/L in the inner medulla). This lets the collecting duct produce concentrated urine.', 'C');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Filter blood plasma under pressure');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Secrete renin');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'Create and maintain the high osmolarity of the medullary interstitium (countercurrent mechanism)');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Reabsorb all the glucose');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 24, 'Genetics & Evolution', 'Monohybrid Cross (Punnett Square)', 'Easy', 'The Punnett square shows a cross between two heterozygous tall pea plants (Tt × Tt). What is the phenotypic ratio of the offspring (tall : dwarf)?', 1, '<svg viewBox="0 0 332 218" xmlns="http://www.w3.org/2000/svg"><rect width="332" height="218" fill="#f8fafc" rx="12"/><text x="206" y="26" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">Gametes of parent 1 (Tt)</text><text x="12" y="126" font-family="Arial" font-size="13" font-weight="700" fill="#475569">Parent 2</text><text x="12" y="144" font-family="Arial" font-size="13" fill="#475569">(Tt)</text><rect x="110" y="42" width="96" height="28" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="158" y="57" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">T</text><rect x="206" y="42" width="96" height="28" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="254" y="57" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">t</text><rect x="66" y="70" width="44" height="62" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="88" y="101" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">T</text><rect x="66" y="132" width="44" height="62" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="88" y="163" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">t</text><rect x="110" y="70" width="96" height="62" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="158" y="101" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="20" fill="#0f172a">TT</text><rect x="206" y="70" width="96" height="62" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="254" y="101" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="20" fill="#0f172a">Tt</text><rect x="110" y="132" width="96" height="62" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="158" y="163" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="20" fill="#0f172a">Tt</text><rect x="206" y="132" width="96" height="62" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="254" y="163" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="20" fill="#0f172a">tt</text></svg>', 'The four squares are TT, Tt, Tt and tt. Three offspring carry at least one dominant T (tall) and one is tt (dwarf), so the phenotypic ratio is 3 tall : 1 dwarf. (The genotypic ratio is 1 TT : 2 Tt : 1 tt.)', 'C');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '1 : 2 : 1');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '1 : 1');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '3 : 1');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '9 : 3 : 3 : 1');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 25, 'Genetics & Evolution', 'Dihybrid Cross (Punnett Square)', 'Medium', 'The 16-square grid shows a dihybrid cross RrYy × RrYy, where R (round) and Y (yellow) are dominant to r (wrinkled) and y (green). How many of the 16 offspring are round and green?', 1, '<svg viewBox="0 0 452 286" xmlns="http://www.w3.org/2000/svg"><rect width="452" height="286" fill="#f8fafc" rx="12"/><text x="266" y="26" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">Gametes of parent 1 (RrYy)</text><text x="12" y="160" font-family="Arial" font-size="13" font-weight="700" fill="#475569">Parent 2</text><text x="12" y="178" font-family="Arial" font-size="13" fill="#475569">(RrYy)</text><rect x="110" y="42" width="78" height="28" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="149" y="57" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">RY</text><rect x="188" y="42" width="78" height="28" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="227" y="57" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">Ry</text><rect x="266" y="42" width="78" height="28" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="305" y="57" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">rY</text><rect x="344" y="42" width="78" height="28" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="383" y="57" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">ry</text><rect x="66" y="70" width="44" height="48" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="88" y="94" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">RY</text><rect x="66" y="118" width="44" height="48" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="88" y="142" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">Ry</text><rect x="66" y="166" width="44" height="48" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="88" y="190" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">rY</text><rect x="66" y="214" width="44" height="48" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="88" y="238" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">ry</text><rect x="110" y="70" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="149" y="94" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">RRYY</text><rect x="188" y="70" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="227" y="94" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">RRYy</text><rect x="266" y="70" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="305" y="94" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">RrYY</text><rect x="344" y="70" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="383" y="94" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">RrYy</text><rect x="110" y="118" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="149" y="142" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">RRYy</text><rect x="188" y="118" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="227" y="142" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">RRyy</text><rect x="266" y="118" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="305" y="142" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">RrYy</text><rect x="344" y="118" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="383" y="142" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">Rryy</text><rect x="110" y="166" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="149" y="190" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">RrYY</text><rect x="188" y="166" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="227" y="190" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">RrYy</text><rect x="266" y="166" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="305" y="190" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">rrYY</text><rect x="344" y="166" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="383" y="190" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">rrYy</text><rect x="110" y="214" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="149" y="238" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">RrYy</text><rect x="188" y="214" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="227" y="238" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">Rryy</text><rect x="266" y="214" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="305" y="238" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">rrYy</text><rect x="344" y="214" width="78" height="48" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="383" y="238" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" fill="#0f172a">rryy</text></svg>', 'Round green seeds have the genotype R_yy: RRyy (1) + Rryy (2) = 3 squares. So 3/16 are round and green.', 'B');
