INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 26, 'Genetics & Evolution', 'Test Cross (Punnett Square)', 'Medium', 'A tall plant (Tt) is crossed with a dwarf plant (tt), as shown in the Punnett square. What is the ratio of tall : dwarf offspring?', 1, '<svg viewBox="0 0 332 218" xmlns="http://www.w3.org/2000/svg"><rect width="332" height="218" fill="#f8fafc" rx="12"/><text x="206" y="26" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">Gametes of parent 1 (Tt)</text><text x="12" y="126" font-family="Arial" font-size="13" font-weight="700" fill="#475569">Parent 2</text><text x="12" y="144" font-family="Arial" font-size="13" fill="#475569">(tt)</text><rect x="110" y="42" width="96" height="28" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="158" y="57" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">T</text><rect x="206" y="42" width="96" height="28" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="254" y="57" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">t</text><rect x="66" y="70" width="44" height="62" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="88" y="101" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">t</text><rect x="66" y="132" width="44" height="62" fill="#fee2e2" stroke="#b91c1c" stroke-width="1.5"/><text x="88" y="163" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="17" font-weight="700" fill="#7f1d1d">t</text><rect x="110" y="70" width="96" height="62" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="158" y="101" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="20" fill="#0f172a">Tt</text><rect x="206" y="70" width="96" height="62" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="254" y="101" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="20" fill="#0f172a">tt</text><rect x="110" y="132" width="96" height="62" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="158" y="163" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="20" fill="#0f172a">Tt</text><rect x="206" y="132" width="96" height="62" fill="#fff" stroke="#94a3b8" stroke-width="1.5"/><text x="254" y="163" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="20" fill="#0f172a">tt</text></svg>', 'Gametes of Tt are T and t; those of tt are only t. The four squares are Tt, tt, Tt and tt: two tall and two dwarf, a 1 : 1 ratio. This is the typical result of a test cross with a heterozygous plant, and it reveals the unknown genotype.', 'B');
