" cy="62" r="10" fill="#fecaca" stroke="#b91c1c" stroke-width="2"/><text x="460" y="62" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="11" font-weight="700" fill="#7f1d1d">P</text><circle cx="460" cy="228" r="10" fill="#fecaca" stroke="#b91c1c" stroke-width="2"/><text x="460" y="228" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="11" font-weight="700" fill="#7f1d1d">P</text><circle cx="60" cy="62" r="10" fill="#fecaca" stroke="#b91c1c" stroke-width="2"/><text x="60" y="62" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="11" font-weight="700" fill="#7f1d1d">P</text><circle cx="60" cy="228" r="10" fill="#fecaca" stroke="#b91c1c" stroke-width="2"/><text x="60" y="228" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="11" font-weight="700" fill="#7f1d1d">P</text><line x1="110" y1="62" x2="110" y2="112" stroke="#0f766e" stroke-width="3"/><polygon points="110.0,50.0 121.4,58.3 117.1,71.7 102.9,71.7 98.6,58.3" fill="#ccfbf1" stroke="#0f766e" stroke-width="2"/><rect x="94" y="97" width="32" height="30" rx="6" fill="#2563eb"/><text x="110" y="112" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="18" font-weight="700" fill="#fff">A</text><line x1="110" y1="228" x2="110" y2="178" stroke="#0f766e" stroke-width="3"/><polygon points="110.0,216.0 121.4,224.3 117.1,237.7 102.9,237.7 98.6,224.3" fill="#ccfbf1" stroke="#0f766e" stroke-width="2"/><rect x="94" y="163" width="32" height="30" rx="6" fill="#dc2626"/><text x="110" y="178" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="18" font-weight="700" fill="#fff">T</text><line x1="105" y1="128" x2="105" y2="162" stroke="#475569" stroke-width="2.2" stroke-dasharray="3 3"/><line x1="115" y1="128" x2="115" y2="162" stroke="#475569" stroke-width="2.2" stroke-dasharray="3 3"/><line x1="210" y1="62" x2="210" y2="112" stroke="#0f766e" stroke-width="3"/>