 y1="128" x2="315" y2="162" stroke="#475569" stroke-width="2.2" stroke-dasharray="3 3"/><line x1="410" y1="62" x2="410" y2="112" stroke="#0f766e" stroke-width="3"/><polygon points="410.0,50.0 421.4,58.3 417.1,71.7 402.9,71.7 398.6,58.3" fill="#ccfbf1" stroke="#0f766e" stroke-width="2"/><rect x="394" y="97" width="32" height="30" rx="6" fill="#d97706"/><text x="410" y="112" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="18" font-weight="700" fill="#fff">C</text><line x1="410" y1="228" x2="410" y2="178" stroke="#0f766e" stroke-width="3"/><polygon points="410.0,216.0 421.4,224.3 417.1,237.7 402.9,237.7 398.6,224.3" fill="#ccfbf1" stroke="#0f766e" stroke-width="2"/><rect x="394" y="163" width="32" height="30" rx="6" fill="#16a34a"/><text x="410" y="178" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="18" font-weight="700" fill="#fff">G</text><line x1="402" y1="128" x2="402" y2="162" stroke="#475569" stroke-width="2.2" stroke-dasharray="3 3"/><line x1="410" y1="128" x2="410" y2="162" stroke="#475569" stroke-width="2.2" stroke-dasharray="3 3"/><line x1="418" y1="128" x2="418" y2="162" stroke="#475569" stroke-width="2.2" stroke-dasharray="3 3"/><g font-family="Arial" font-size="15" font-weight="700" fill="#0f172a"><text x="14" y="66">5''</text><text x="482" y="66">3''</text><text x="14" y="232">3''</text><text x="482" y="232">5''</text></g><g class="tg"><line x1="160" y1="54" x2="160" y2="22" stroke="#334155" stroke-width="1.5"/><circle cx="160" cy="54" r="3" fill="#334155"/></g><g class="tg"><circle cx="160" cy="22" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="160" y="22.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">A</text></g><g class="tg"><line x1="214" y1="54" x2="232" y2="22" stroke="#334155" stroke-width="1.5"/><circle cx="214" cy="54" r="3" fill="#334155"/></g><g class="tg"><circle cx="232" cy="22" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="232" y="22.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">B</text></g><g class="tg"><line x1="105" y1="145" x2="52" y2="145" stroke="#334155" stroke-width="1.5"/><circle cx="105" cy="145" r="3" fill="#334155"/></g><g class="tg"><circle cx="52" cy="145" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="52" y="145.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">C</text></g><g class="tg"><line x1="218" y1="145" x2="258" y2="145" stroke="#334155" stroke-width="1.5"/><circle cx="218" cy="145" r="3" fill="#334155"/></g><g class="tg"><circle cx="258" cy="145" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="258" y="145.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">D</text></g><g class="tg"><line x1="318" y1="118" x2="362" y2="145" stroke="#334155" stroke-width="1.5"/><circle cx="318" cy="118" r="3" fill="#334155"/></g><g class="tg"><circle cx="362" cy="145" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="362" y="145.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">E</text></g></svg>', 'Guanine pairs with cytosine through three hydrogen bonds (G≡C), while adenine pairs with thymine through two (A=T). This is why DNA rich in G-C pairs is more stable and has a higher melting temperature.', 'C');
