INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 29, 'Genetics & Evolution', 'DNA Replication (Diagram)', 'Hard', 'In this replication fork, the new strand labelled B is synthesised:', 1, '<svg viewBox="0 0 560 336" xmlns="http://www.w3.org/2000/svg"><rect width="560" height="336" fill="#f8fafc" rx="12"/><path d="M20 155 H190 M20 175 H190" stroke="#0f172a" stroke-width="4.5" stroke-linecap="round" fill="none"/><path d="M190 155 L469.0 44.0" stroke="#0f172a" stroke-width="4.5" stroke-linecap="round"/><path d="M190 175 L469.0 286.0" stroke="#0f172a" stroke-width="4.5" stroke-linecap="round"/><line x1="232.4" y1="153.2" x2="446.3" y2="68.1" stroke="#dc2626" stroke-width="4.5" stroke-linecap="round"/><polygon points="221.2,157.7 236.5,158.1 232.0,146.9" fill="#dc2626"/><line x1="232.4" y1="176.8" x2="278.9" y2="195.3" stroke="#2563eb" stroke-width="4.5" stroke-linecap="round"/><polygon points="290.0,199.7 279.2,189.0 274.8,200.1" fill="#2563eb"/><rect x="227.4" y="171.8" width="10" height="10" rx="2" fill="#f59e0b" stroke="#92400e" stroke-width="1.5"/><line x1="295.6" y1="201.9" x2="342.1" y2="220.4" stroke="#2563eb" stroke-width="4.5" stroke-linecap="round"/><polygon points="353.3,224.9 342.5,214.1 338.0,225.3" fill="#2563eb"/><rect x="290.6" y="196.9" width="10" height="10" rx="2" fill="#f59e0b" stroke="#92400e" stroke-width="1.5"/><line x1="358.9" y1="227.1" x2="405.4" y2="245.6" stroke="#2563eb" stroke-width="4.5" stroke-linecap="round"/><polygon points="416.5,250.0 405.7,239.3 401.3,250.4" fill="#2563eb"/><rect x="353.9" y="222.1" width="10" height="10" rx="2" fill="#f59e0b" stroke="#92400e" stroke-width="1.5"/><line x1="422.1" y1="252.3" x2="468.6" y2="270.8" stroke="#2563eb" stroke-width="4.5" stroke-linecap="round"/><polygon points="479.8,275.2 469.0,264.4 464.5,275.6" fill="#2563eb"/><rect x="417.1" y="247.3" width="10" height="10" rx="2" fill="#f59e0b" stroke="#92400e" stroke-width="1.5"/><ellipse cx="301.1" cy="136.4" rx="28" ry="15" transform="rotate(-20 301.1 136.4)" fill="#bae6fd" fill-opacity="0.9" stroke="#0369a1" stroke-width="2.5"/><circle cx="196" cy="165" r="15" fill="#fde68a" stroke="#b45309" stroke-width="3"/><path d="M150 308 H40" stroke="#475569" stroke-width="3"/><polygon points="30,308 44,300 44,316" fill="#475569"/><text x="40" y="327" font-family="Arial" font-size="12" fill="#475569">direction of fork movement</text><g class="tg"><line x1="196" y1="165" x2="118" y2="92" stroke="#334155" stroke-width="1.5"/><circle cx="196" cy="165" r="3" fill="#334155"/></g><g class="tg"><circle cx="118" cy="92" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="118" y="92.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">A</text></g><g class="tg"><line x1="385.83" y1="92.17" x2="452" y2="22" stroke="#334155" stroke-width="1.5"/><circle cx="385.83" cy="92.17" r="3" fill="#334155"/></g><g class="tg"><circle cx="452" cy="22" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="452" y="22.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">B</text></g><g class="tg"><line x1="382.11" y1="236.35" x2="500" y2="296" stroke="#334155" stroke-width="1.5"/><circle cx="382.11" cy="236.35" r="3" fill="#334155"/></g><g class="tg"><circle cx="500" cy="296" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="500" y="296.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">C</text></g><g class="tg"><line x1="295.62" y1="201.94" x2="250" y2="290" stroke="#334155" stroke-width="1.5"/><circle cx="295.62" cy="201.94" r="3" fill="#334155"/></g><g class="tg"><circle cx="250" cy="290" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="250" y="290.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">D</text></g><g class="tg"><line x1="301.106" y1="136.434" x2="232" y2="40" stroke="#334155" stroke-width="1.5"/><circle cx="301.106" cy="136.434" r="3" fill="#334155"/></g><g class="tg"><circle cx="232" cy="40" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="232" y="40.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">E</text></g><g class="tg"><line x1="90" y1="155" x2="62" y2="108" stroke="#334155" stroke-width="1.5"/><circle cx="90" cy="155" r="3" fill="#334155"/></g><g class="tg"><circle cx="62" cy="108" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="62" y="108.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">F</text></g></svg>', 'DNA polymerase adds nucleotides only in the 5'' to 3'' direction. On the template that is read 3'' to 5'' towards the fork, the new strand (leading) is made continuously; on the other template, short Okazaki fragments (lagging strand) are made away from the fork and joined by DNA ligase.', 'A');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Continuously, in the same direction as the fork opens (towards the fork)');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Discontinuously as Okazaki fragments, away from the fork');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'Only after the lagging strand is complete');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Without any template');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 30, 'Genetics & Evolution', 'lac Operon (Diagram)', 'Hard', 'In the lac operon of E. coli, the gene labelled E codes for a protein that, in the absence of lactose, binds to the operator. What is this protein?', 1, '<svg viewBox="0 0 580 262" xmlns="http://www.w3.org/2000/svg"><rect width="580" height="262" fill="#f8fafc" rx="12"/><rect x="30" y="118" width="520" height="48" rx="6" fill="#e2e8f0" stroke="#64748b" stroke-width="2"/><rect x="40" y="124" width="72" height="36" rx="4" fill="#fde68a" stroke="#334155" stroke-width="2"/><text x="76" y="142.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="15" font-weight="700" font-style="italic" fill="#0f172a">lac i</text><rect x="120" y="124" width="44" height="36" rx="4" fill="#bfdbfe" stroke="#334155" stroke-width="2"/><text x="142" y="142.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="15" font-weight="700" font-style="italic" fill="#0f172a">P</text><rect x="170" y="124" width="38" height="36" rx="4" fill="#fecaca" stroke="#334155" stroke-width="2"/><text x="189" y="142.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="15" font-weight="700" font-style="italic" fill="#0f172a">O</text><rect x="216" y="124" width="104" height="36" rx="4" fill="#bbf7d0" stroke="#334155" stroke-width="2"/><text x="268" y="142.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="15" font-weight="700" font-style="italic" fill="#0f172a">lac Z</text><rect x="326" y="124" width="86" height="36" rx="4" fill="#c7d2fe" stroke="#334155" stroke-width="2"/><text x="369" y="142.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="15" font-weight="700" font-style="italic" fill="#0f172a">lac Y</text><rect x="418" y="124" width="92" height="36" rx="4" fill="#fbcfe8" stroke="#334155" stroke-width="2"/><text x="464" y="142.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="15" font-weight="700" font-style="italic" fill="#0f172a">lac A</text><path d="M216 96 H500" stroke="#dc2626" stroke-width="3.5" fill="none"/><polygon points="512,96 498,88 498,104" fill="#dc2626"/><text x="364" y="84" text-anchor="middle" font-family="Arial" font-size="12" fill="#7f1d1d">single polycistronic mRNA</text><path d="M76 118 V90" stroke="#64748b" stroke-width="2" stroke-dasharray="4 3" fill="none"/><circle cx="76" cy="58" r="30" fill="#fca5a5" stroke="#b91c1c" stroke-width="2.5"/><text x="76" y="58.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="12" font-weight="700" fill="#7f1d1d">protein</text><g class="tg"><line x1="76" y1="167" x2="76" y2="232" stroke="#334155" stroke-width="1.5"/><circle cx="76" cy="167" r="3" fill="#334155"/></g><g class="tg"><circle cx="76" cy="232" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="76" y="232.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">E</text></g><g class="tg"><line x1="142" y1="167" x2="142" y2="232" stroke="#334155" stroke-width="1.5"/><circle cx="142" cy="167" r="3" fill="#334155"/></g><g class="tg"><circle cx="142" cy="232" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="142" y="232.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">D</text></g><g class="tg"><line x1="189" y1="167" x2="189" y2="232" stroke="#334155" stroke-width="1.5"/><circle cx="189" cy="167" r="3" fill="#334155"/></g><g class="tg"><circle cx="189" cy="232" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="189" y="232.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">A</text></g><g class="tg"><line x1="268" y1="167" x2="268" y2="232" stroke="#334155" stroke-width="1.5"/><circle cx="268" cy="167" r="3" fill="#334155"/></g><g class="tg"><circle cx="268" cy="232" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="268" y="232.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">F</text></g><g class="tg"><line x1="369" y1="167" x2="369" y2="232" stroke="#334155" stroke-width="1.5"/><circle cx="369" cy="167" r="3" fill="#334155"/></g><g class="tg"><circle cx="369" cy="232" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="369" y="232.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">C</text></g><g class="tg"><line x1="464" y1="167" x2="464" y2="232" stroke="#334155" stroke-width="1.5"/><circle cx="464" cy="167" r="3" fill="#334155"/></g><g class="tg"><circle cx="464" cy="232" r="12" fill="#fff" stroke="#b91c1c" stroke-width="2.2"/><text x="464" y="232.5" text-anchor="middle" dominant-baseline="central" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#b91c1c">B</text></g></svg>', 'The regulator (i) gene is expressed constitutively and makes the repressor protein. Without lactose the repressor binds the operator and blocks transcription of lac Z, Y and A; allolactose (the inducer) binds the repressor and releases the operator.', 'A');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Repressor');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'RNA polymerase');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'Beta-galactosidase');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Permease');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 31, 'Genetics & Evolution', 'Pedigree Analysis (Diagram)', 'Hard', 'In the pedigree chart shown, a trait appears in individual 5 although both her parents (1 and 2) are unaffected. What is the most likely mode of inheritance?', 1, '<svg viewBox="0 0 434 362" xmlns="http://www.w3.org/2000/svg"><rect width="434" height="362" fill="#f8fafc" rx="12"/><line x1="199" y1="56" x2="285" y2="56" stroke="#0f172a" stroke-width="2.5"/><line x1="285" y1="168" x2="371" y2="168" stroke="#0f172a" stroke-width="2.5"/><line x1="242" y1="56" x2="242" y2="132" stroke="#0f172a" stroke-width="2.5"/><line x1="113" y1="132" x2="285" y2="132" stroke="#0f172a" stroke-width="2.5"/><line x1="113" y1="132" x2="113" y2="151" stroke="#0f172a" stroke-width="2.5"/><line x1="199" y1="132" x2="199" y2="151" stroke="#0f172a" stroke-width="2.5"/><line x1="285" y1="132" x2="285" y2="151" stroke="#0f172a" stroke-width="2.5"/><line x1="328" y1="168" x2="328" y2="244" stroke="#0f172a" stroke-width="2.5"/><line x1="199" y1="244" x2="328" y2="244" stroke="#0f172a" stroke-width="2.5"/><line x1="199" y1="244" x2="199" y2="263" stroke="#0f172a" stroke-width="2.5"/><line x1="285" y1="244" x2="285" y2="263" stroke="#0f172a" stroke-width="2.5"/><rect x="183" y="40" width="32" height="32" fill="#fff" stroke="#0f172a" stroke-width="2.5"/><text x="199" y="92" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">1</text><circle cx="285" cy="56" r="17" fill="#fff" stroke="#0f172a" stroke-width="2.5"/><text x="285" y="92" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">2</text><rect x="97" y="152" width="32" height="32" fill="#fff" stroke="#0f172a" stroke-width="2.5"/><text x="113" y="204" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">3</text><circle cx="199" cy="168" r="17" fill="#fff" stroke="#0f172a" stroke-width="2.5"/><text x="199" y="204" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">4</text><circle cx="285" cy="168" r="17" fill="#0f172a" stroke="#0f172a" stroke-width="2.5"/><text x="285" y="204" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">5</text><rect x="355" y="152" width="32" height="32" fill="#fff" stroke="#0f172a" stroke-width="2.5"/><text x="371" y="204" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">6</text><circle cx="199" cy="280" r="17" fill="#fff" stroke="#0f172a" stroke-width="2.5"/><text x="199" y="316" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">7</text><rect x="269" y="264" width="32" height="32" fill="#fff" stroke="#0f172a" stroke-width="2.5"/><text x="285" y="316" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">8</text><text x="14" y="61" font-family="Arial" font-size="15" font-weight="700" fill="#b91c1c">I</text><text x="14" y="173" font-family="Arial" font-size="15" font-weight="700" fill="#b91c1c">II</text><text x="14" y="285" font-family="Arial" font-size="15" font-weight="700" fill="#b91c1c">III</text><g font-family="Arial" font-size="12" fill="#334155"><rect x="14" y="332" width="12" height="12" fill="#0f172a"/><text x="32" y="342">affected</text><rect x="100" y="332" width="12" height="12" fill="#fff" stroke="#0f172a" stroke-width="2"/><text x="118" y="342">unaffected   (square = male, circle = female)</text></g></svg>', 'Two unaffected parents with an affected child means the trait is recessive (an unaffected carrier pair). An affected daughter cannot come from an unaffected father in X-linked recessive inheritance, since the father would have to give her an X carrying the allele and would himself be affected, so the trait is autosomal recessive.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Autosomal dominant');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Autosomal recessive');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'X-linked recessive');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'X-linked dominant');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 32, 'Genetics & Evolution', 'Pedigree Analysis (Diagram)', 'Hard', 'In this pedigree only males are affected, and the trait passes through unaffected females and is never passed from father to son. What is the most likely mode of inheritance?', 1, '<svg viewBox="0 0 380 362" xmlns="http://www.w3.org/2000/svg"><rect width="380" height="362" fill="#f8fafc" rx="12"/><line x1="156" y1="56" x2="242" y2="56" stroke="#0f172a" stroke-width="2.5"/><line x1="199" y1="168" x2="285" y2="168" stroke="#0f172a" stroke-width="2.5"/><line x1="199" y1="56" x2="199" y2="132" stroke="#0f172a" stroke-width="2.5"/><line x1="113" y1="132" x2="199" y2="132" stroke="#0f172a" stroke-width="2.5"/><line x1="113" y1="132" x2="113" y2="151" stroke="#0f172a" stroke-width="2.5"/><line x1="199" y1="132" x2="199" y2="151" stroke="#0f172a" stroke-width="2.5"/><line x1="242" y1="168" x2="242" y2="244" stroke="#0f172a" stroke-width="2.5"/><line x1="113" y1="244" x2="285" y2="244" stroke="#0f172a" stroke-width="2.5"/><line x1="113" y1="244" x2="113" y2="263" stroke="#0f172a" stroke-width="2.5"/><line x1="199" y1="244" x2="199" y2="263" stroke="#0f172a" stroke-width="2.5"/><line x1="285" y1="244" x2="285" y2="263" stroke="#0f172a" stroke-width="2.5"/><rect x="140" y="40" width="32" height="32" fill="#fff" stroke="#0f172a" stroke-width="2.5"/><text x="156" y="92" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">1</text><circle cx="242" cy="56" r="17" fill="#fff" stroke="#0f172a" stroke-width="2.5"/><text x="242" y="92" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">2</text><rect x="97" y="152" width="32" height="32" fill="#0f172a" stroke="#0f172a" stroke-width="2.5"/><text x="113" y="204" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">3</text><circle cx="199" cy="168" r="17" fill="#fff" stroke="#0f172a" stroke-width="2.5"/><text x="199" y="204" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">4</text><rect x="269" y="152" width="32" height="32" fill="#fff" stroke="#0f172a" stroke-width="2.5"/><text x="285" y="204" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">5</text><rect x="97" y="264" width="32" height="32" fill="#0f172a" stroke="#0f172a" stroke-width="2.5"/><text x="113" y="316" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">6</text><circle cx="199" cy="280" r="17" fill="#fff" stroke="#0f172a" stroke-width="2.5"/><text x="199" y="316" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">7</text><rect x="269" y="264" width="32" height="32" fill="#fff" stroke="#0f172a" stroke-width="2.5"/><text x="285" y="316" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#475569">8</text><text x="14" y="61" font-family="Arial" font-size="15" font-weight="700" fill="#b91c1c">I</text><text x="14" y="173" font-family="Arial" font-size="15" font-weight="700" fill="#b91c1c">II</text><text x="14" y="285" font-family="Arial" font-size="15" font-weight="700" fill="#b91c1c">III</text><g font-family="Arial" font-size="12" fill="#334155"><rect x="14" y="332" width="12" height="12" fill="#0f172a"/><text x="32" y="342">affected</text><rect x="100" y="332" width="12" height="12" fill="#fff" stroke="#0f172a" stroke-width="2"/><text x="118" y="342">unaffected   (square = male, circle = female)</text></g></svg>', 'Unaffected carrier mothers pass an X carrying the allele to their sons, who are affected because they have only one X. Fathers cannot pass it to sons (sons get the Y), and affected males appear in alternate generations. This is X-linked recessive, like haemophilia and colour blindness. Y-linked traits would pass from every affected father to all his sons.', 'C');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Autosomal dominant');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Autosomal recessive');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'X-linked recessive');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Y-linked');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 33, 'Genetics & Evolution', 'Chargaff''s Rule', 'Medium', 'In a double-stranded DNA molecule, 30 per cent of the bases are adenine. What percentage of the bases is guanine?', 0, NULL, 'By Chargaff''s rule A = T and G = C. If A = 30 per cent then T = 30 per cent, so A + T = 60 per cent and G + C = 40 per cent, which means G = 20 per cent.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '30%');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '20%');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '40%');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '70%');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 34, 'Genetics & Evolution', 'Hardy-Weinberg Principle', 'Hard', 'In a population in Hardy-Weinberg equilibrium, 4 per cent of the individuals show a recessive trait. What percentage of the population are heterozygous carriers?', 0, NULL, 'q^2 = 0.04 so q = 0.2 and p = 1 − 0.2 = 0.8. The frequency of heterozygotes is 2pq = 2 × 0.8 × 0.2 = 0.32, that is 32 per cent.', 'A');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '32%');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '16%');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '64%');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '8%');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 35, 'Genetics & Evolution', 'Evolution: Natural Selection', 'Medium', 'The increase in the proportion of dark (melanic) peppered moths, Biston betularia, in industrial areas of England during the 19th century is an example of:', 0, NULL, 'In polluted woods darkened by soot, dark moths were better camouflaged from birds and survived and reproduced more, so the frequency of the melanic allele rose. This is natural selection, supporting Darwin''s theory.', 'A');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Natural selection (adaptive change)');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Genetic drift');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'The founder effect');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Inheritance of acquired characters');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 36, 'Ecology & Environment', 'Energy Flow and the 10% Law (Diagram)', 'Medium', 'The energy pyramid shows that producers fix 20,000 kJ of energy. According to the 10 per cent law, how much energy is available to the tertiary consumers?', 1, '<svg viewBox="0 0 520 208" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="208" fill="#f8fafc" rx="12"/><polygon points="57.5,148 262.5,148 290,192 30,192" fill="#b91c1c" stroke="#fff" stroke-width="3"/><text x="160" y="170" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="15" font-weight="700" fill="#fff">20,000 kJ</text><text x="318" y="170" dominant-baseline="central" font-family="Arial" font-size="14" fill="#0f172a">Producers</text><polygon points="85,104 235,104 262.5,148 57.5,148" fill="#dc2626" stroke="#fff" stroke-width="3"/><text x="160" y="126" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="15" font-weight="700" fill="#fff">?</text><text x="318" y="126" dominant-baseline="central" font-family="Arial" font-size="14" fill="#0f172a">Primary consumers</text><polygon points="112.5,60 207.5,60 235,104 85,104" fill="#ef4444" stroke="#fff" stroke-width="3"/><text x="160" y="82" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="15" font-weight="700" fill="#fff">?</text><text x="318" y="82" dominant-baseline="central" font-family="Arial" font-size="14" fill="#0f172a">Secondary consumers</text><polygon points="140,16 180,16 207.5,60 112.5,60" fill="#f87171" stroke="#fff" stroke-width="3"/><text x="160" y="38" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="15" font-weight="700" fill="#fff">?</text><text x="318" y="38" dominant-baseline="central" font-family="Arial" font-size="14" fill="#0f172a">Tertiary consumers</text></svg>', 'Only about 10 per cent of the energy at one trophic level passes to the next: producers 20,000 kJ → primary consumers 2,000 kJ → secondary consumers 200 kJ → tertiary consumers 20 kJ.', 'D');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '2 kJ');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '200 kJ');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '2,000 kJ');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '20 kJ');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 37, 'Ecology & Environment', 'Nitrogen Cycle (Flow Diagram)', 'Medium', 'In the nitrogen cycle shown, what is the process marked "?" by which atmospheric nitrogen is converted into ammonia?', 1, '<svg viewBox="0 0 580 430" xmlns="http://www.w3.org/2000/svg"><rect width="580" height="430" fill="#f8fafc" rx="12"/><text x="290" y="26" text-anchor="middle" font-family="Arial" font-size="15" font-weight="700" fill="#0f172a">Nitrogen cycle</text><line x1="328.2" y1="119.0" x2="460.0" y2="201.7" stroke="#475569" stroke-width="2.6"/><polygon points="466.8,206.0 452.6,204.2 459.0,194.0" fill="#475569"/><text x="397.5" y="151.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="12" font-weight="700" fill="#7f1d1d" stroke="#f8fafc" stroke-width="4" paint-order="stroke">?</text><line x1="466.8" y1="254.0" x2="335.0" y2="336.7" stroke="#475569" stroke-width="2.6"/><polygon points="328.2,341.0 336.0,329.0 342.4,339.2" fill="#475569"/><text x="397.5" y="286.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="12" font-weight="700" fill="#7f1d1d" stroke="#f8fafc" stroke-width="4" paint-order="stroke">Nitrification</text><line x1="251.8" y1="341.0" x2="120.0" y2="258.3" stroke="#475569" stroke-width="2.6"/><polygon points="113.2,254.0 127.4,255.8 121.0,266.0" fill="#475569"/><text x="182.5" y="286.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="12" font-weight="700" fill="#7f1d1d" stroke="#f8fafc" stroke-width="4" paint-order="stroke">Nitrification</text><line x1="113.2" y1="206.0" x2="245.0" y2="123.3" stroke="#475569" stroke-width="2.6"/><polygon points="251.8,119.0 244.0,131.0 237.6,120.8" fill="#475569"/><text x="182.5" y="151.5" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="12" font-weight="700" fill="#7f1d1d" stroke="#f8fafc" stroke-width="4" paint-order="stroke">Denitrification</text><rect x="218.2" y="74.0" width="143.6" height="42" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="290.0" y="95.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Atmospheric N2</text><rect x="433.2" y="209.0" width="143.6" height="42" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="505.0" y="230.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Ammonia (NH4+)</text><rect x="218.2" y="344.0" width="143.6" height="42" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="290.0" y="365.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Nitrite (NO2-)</text><rect x="3.2" y="209.0" width="143.6" height="42" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="75.0" y="230.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Nitrate (NO3-)</text></svg>', 'Nitrogen-fixing organisms (Rhizobium in legume root nodules, Azotobacter, Anabaena, and others) reduce atmospheric N_2 to ammonia using the enzyme nitrogenase. Nitrification oxidises ammonia to nitrite and nitrate; denitrification returns N_2 to the air.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Nitrification');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Biological nitrogen fixation');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'Denitrification');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Ammonification');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 38, 'Ecology & Environment', 'Population Growth (Graph)', 'Medium', 'The graph shows the growth of a population in a limited habitat. The carrying capacity (K) of the habitat is about:', 1, '<svg viewBox="0 0 540 320" xmlns="http://www.w3.org/2000/svg"><rect width="540" height="320" fill="#f8fafc" rx="12"/><text x="270" y="26" text-anchor="middle" font-family="Arial" font-size="15" font-weight="700" fill="#0f172a">Growth of a population in a limited habitat</text><line x1="78" y1="256.0" x2="516" y2="256.0" stroke="#64748b" stroke-width="1"/><text x="71" y="256.0" text-anchor="end" dominant-baseline="central" font-family="Arial" font-size="11" fill="#475569">0</text><line x1="78" y1="207.5" x2="516" y2="207.5" stroke="#e2e8f0" stroke-width="1"/><text x="71" y="207.5" text-anchor="end" dominant-baseline="central" font-family="Arial" font-size="11" fill="#475569">20</text><line x1="78" y1="159.0" x2="516" y2="159.0" stroke="#e2e8f0" stroke-width="1"/><text x="71" y="159.0" text-anchor="end" dominant-baseline="central" font-family="Arial" font-size="11" fill="#475569">40</text><line x1="78" y1="110.5" x2="516" y2="110.5" stroke="#e2e8f0" stroke-width="1"/><text x="71" y="110.5" text-anchor="end" dominant-baseline="central" font-family="Arial" font-size="11" fill="#475569">60</text><line x1="78" y1="62.0" x2="516" y2="62.0" stroke="#e2e8f0" stroke-width="1"/><text x="71" y="62.0" text-anchor="end" dominant-baseline="central" font-family="Arial" font-size="11" fill="#475569">80</text><line x1="78" y1="62" x2="78" y2="256" stroke="#64748b" stroke-width="1.6"/><text x="105.4" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">0</text><text x="160.1" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">2</text><text x="214.9" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">4</text><text x="269.6" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">6</text><text x="324.4" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">8</text><text x="379.1" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">10</text><text x="433.9" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">12</text><text x="488.6" y="274" text-anchor="middle" font-family="Arial" font-size="12" fill="#0f172a">14</text><polyline points="105.4,246.3 160.1,231.8 214.9,197.8 269.6,134.8 324.4,81.4 379.1,62.0 433.9,62.0 488.6,62.0" fill="none" stroke="#dc2626" stroke-width="3" stroke-linejoin="round"/><circle cx="105.4" cy="246.3" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="105.4" y="237.3" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">4</text><circle cx="160.1" cy="231.8" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="160.1" y="222.8" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">10</text><circle cx="214.9" cy="197.8" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="214.9" y="188.8" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">24</text><circle cx="269.6" cy="134.8" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="269.6" y="125.8" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">50</text><circle cx="324.4" cy="81.4" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="324.4" y="72.4" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">72</text><circle cx="379.1" cy="62.0" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="379.1" y="53.0" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">80</text><circle cx="433.9" cy="62.0" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="433.9" y="53.0" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">80</text><circle cx="488.6" cy="62.0" r="4" fill="#fff" stroke="#dc2626" stroke-width="2.5"/><text x="488.6" y="53.0" text-anchor="middle" font-family="Arial" font-size="10" font-weight="700" fill="#0f172a">80</text><text x="297" y="308" text-anchor="middle" font-family="Arial" font-size="12" font-weight="700" fill="#475569">Time (days)</text><text transform="translate(16 159) rotate(-90)" text-anchor="middle" font-family="Arial" font-size="12" font-weight="700" fill="#475569">Number of individuals</text></svg>', 'The curve is S-shaped (logistic): growth slows as resources become limiting and the population levels off at the carrying capacity, here about 80 individuals.', 'C');
