INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 39, 'Ecology & Environment', 'Food Chains (Flow Diagram)', 'Medium', 'In the grassland food chain shown, the eagle is a:', 1, '<svg viewBox="0 0 550 340" xmlns="http://www.w3.org/2000/svg"><rect width="550" height="340" fill="#f8fafc" rx="12"/><text x="290" y="26" text-anchor="middle" font-family="Arial" font-size="15" font-weight="700" fill="#0f172a">A grassland food chain</text><line x1="151.0" y1="90.0" x2="204.8" y2="90.0" stroke="#475569" stroke-width="2.6"/><polygon points="212.8,90.0 199.8,96.0 199.8,84.0" fill="#475569"/><line x1="337.2" y1="90.0" x2="391.0" y2="90.0" stroke="#475569" stroke-width="2.6"/><polygon points="399.0,90.0 386.0,96.0 386.0,84.0" fill="#475569"/><path d="M445.0 111.0 V150.0 H105.0 V179.0" fill="none" stroke="#475569" stroke-width="2.6"/><polygon points="105.0,189.0 99.0,176.0 111.0,176.0" fill="#475569"/><line x1="151.0" y1="210.0" x2="221.0" y2="210.0" stroke="#475569" stroke-width="2.6"/><polygon points="229.0,210.0 216.0,216.0 216.0,204.0" fill="#475569"/><rect x="62.0" y="69.0" width="86.0" height="42" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="105.0" y="90.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Grass</text><rect x="215.8" y="69.0" width="118.4" height="42" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="275.0" y="90.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Grasshopper</text><rect x="402.0" y="69.0" width="86.0" height="42" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="445.0" y="90.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Frog</text><rect x="62.0" y="189.0" width="86.0" height="42" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="105.0" y="210.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Snake</text><rect x="232.0" y="189.0" width="86.0" height="42" rx="10" fill="#fee2e2" stroke="#b91c1c" stroke-width="2.5"/><text x="275.0" y="210.0" text-anchor="middle" dominant-baseline="central" font-family="Arial" font-size="14" font-weight="700" fill="#0f172a">Eagle</text></svg>', 'Grass (producer) is the 1st trophic level, grasshopper (primary consumer) the 2nd, frog (secondary consumer) the 3rd, snake (tertiary consumer) the 4th and the eagle (quaternary consumer) the 5th.', 'A');
