INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@bio_exam, 40, 'Ecology & Environment', 'Ecological Succession', 'Easy', 'The pioneer species in primary succession on a bare rock (xerarch succession) are usually:', 0, NULL, 'Crustose lichens secrete acids that weather the rock and make the first soil. They are followed by mosses, herbs, shrubs and finally the climax forest.', 'B');
